# Instructions ----
# This file follows the format generated by FIMS:::use_testthat_template().
# Necessary tests include input and output (IO) correctness, edge-case
# handling, and built-in errors and warnings.

test_that("DSEMInterface can be created and configured", {
  # Description: Test that the DSEMInterface Rcpp object can be instantiated
  # and its fields can be correctly set and retrieved from R.

  # 1. Setup
  # Ensure the Rcpp module is loaded. This is usually handled by devtools::load_all()
  # but can be called explicitly if needed.
  FIMS::initialize_module_objects()

  # 2. IO Correctness
  # Test that the DSEMInterface object can be created
  dsem_interface <- new(DSEM)
  testthat::expect_s4_class(dsem_interface, "Rcpp_DSEM")

  # Test that properties can be set
  dsem_interface$n_time <- 2
  dsem_interface$n_variables <- 1
  testthat::expect_equal(dsem_interface$n_time, 2)
  testthat::expect_equal(dsem_interface$n_variables, 1)

  # Define a simple RAM matrix for an AR(1) process
  # Global indices: state 1 is var1@t1, state 2 is var1@t2
  ram_matrix <- matrix(c(
    # type, from, to, beta_index
    1, 1, 2, 1, # Path 1: AR(1) path from var1@t1 to var1@t2 (rho)
    2, 1, 1, 2, # Path 2: Variance for var1@t1 (sd1)
    2, 2, 2, 3 # Path 3: Variance for var1@t2 (sd2)
  ), ncol = 4, byrow = TRUE)
  dsem_interface$ram_matrix <- ram_matrix
  testthat::expect_equal(dsem_interface$ram_matrix, ram_matrix)

  # Test that beta_z can be set
  rho <- 0.8
  sd1 <- 1.2
  sd2 <- 0.5
  dsem_interface$beta_z$resize(3)
  dsem_interface$beta_z$set_values(c(rho, sd1, sd2))
  dsem_interface$beta_z$set_estimation_types(
    c("fixed_effects", "constant", "constant")
  )

  # Check values by accessing them (note: at() is 1-based)
  testthat::expect_equal(dsem_interface$beta_z$at(1)$initial_value_m, rho)
  testthat::expect_equal(dsem_interface$beta_z$at(2)$initial_value_m, sd1)
  testthat::expect_equal(dsem_interface$beta_z$at(3)$initial_value_m, sd2)
  testthat::expect_equal(dsem_interface$beta_z$at(1)$estimation_type_m$get(), "fixed_effects")
})

test_that("DSEMInterface handles edge cases", {
  # Description: Test the DSEMInterface with minimal dimensions.
  dsem_interface <- new(DSEM)

  # Test with a single state (1 time step, 1 variable)
  dsem_interface$n_time <- 1
  dsem_interface$n_variables <- 1

  ram_matrix <- matrix(c(
    # type, from, to, beta_index
    2, 1, 1, 1 # Variance for the single state
  ), ncol = 4, byrow = TRUE)
  dsem_interface$ram_matrix <- ram_matrix
  testthat::expect_equal(dsem_interface$ram_matrix, ram_matrix)

  sd_val <- 2.0
  dsem_interface$beta_z$resize(1)
  dsem_interface$beta_z$set_values(sd_val)
  testthat::expect_equal(dsem_interface$beta_z$at(1)$initial_value_m, sd_val)
})

